mapper.select:
SELECT o.id AS id, o.order_no AS orderNo, o.merchant_id AS merchantId, m.shop_name AS shopName, o.total_amount AS totalAmount, o.pay_amount AS payAmount, o.status AS status, o.pay_time AS payTime, o.pay_method AS payMethod, o.receiver_name AS receiverName, o.receiver_phone AS receiverPhone, o.receiver_address AS receiverAddress, o.remark AS remark, o.create_time AS createTime FROM `order` o LEFT JOIN merchant m ON o.merchant_id = m.id AND m.deleted = 0 WHERE o.user_id = #{userId} AND o.deleted = 0
AND o.status = #{status}
ORDER BY o.create_time DESC

SELECT o.id AS id, o.order_no AS orderNo, o.user_id AS userId, o.merchant_id AS merchantId, m.shop_name AS shopName, o.total_amount AS totalAmount, o.pay_amount AS payAmount, o.status AS status, o.pay_time AS payTime, o.pay_method AS payMethod, o.receiver_name AS receiverName, o.receiver_phone AS receiverPhone, o.receiver_address AS receiverAddress, o.remark AS remark, o.create_time AS createTime FROM `order` o LEFT JOIN merchant m ON o.merchant_id = m.id AND m.deleted = 0
o.deleted = 0
AND o.order_no LIKE CONCAT('%', #{params.orderNo}, '%')
AND o.status = #{params.status}
AND o.merchant_id = #{params.merchantId}
ORDER BY o.create_time DESC
